let arguments raw =
  let input = field "input" raw in
  let request = Realization_request.of_json (field "request" input) in
  let config = match field "config" input with Json.Null -> None | value -> Some (A.Config.of_json value) in
  request, config
let source_json = function
  | None -> Json.Null
  | Some (source : Behavior.source_location) -> Json.Object ["file",Json.String source.file;
      "line",Json.Int source.line;"function",Json.String source.function_name]
let same_json left right = Canonical.encode left = Canonical.encode right
let run raw =
  let request, config = arguments raw in
  if Json.string (field "api" raw) = "generate_synthetic" then G.generate ?config request
  else G.propose ?config request
let check_literal text =
  let raw = Json.parse text in
  let expected = field "expected" raw and label = Json.string (field "id" raw) in
  match run raw with
  | actual ->
      require (Json.string (field "outcome" raw) = "returned") (label ^ ": missing rejection");
      require (same_json (A.Candidate.to_json actual) (field "candidate" expected)) (label ^ ": complete candidate mismatch");
      require (A.Candidate.fingerprint actual = Json.string (field "fingerprint" expected)) (label ^ ": candidate fingerprint mismatch")
  | exception G.Unsupported error ->
      require (Json.string (field "outcome" raw) = "raised") (label ^ ": unexpected rejection: " ^ G.format_error error);
      require (G.format_error error = Json.string (field "message" expected)) (label ^ ": formatted diagnostic mismatch");
      require (error.message = Json.string (field "plain" expected)) (label ^ ": plain diagnostic mismatch");
      require ((match error.node_id with None -> Json.Null | Some value -> Json.String value) = field "node_id" expected)
        (label ^ ": source identity mismatch");
      require (same_json (source_json error.source) (field "source" expected)) (label ^ ": complete source coordinates mismatch")
let rejected code action = match action () with
  | _ -> failwith ("Expected resource/authority rejection: " ^ code)
  | exception Diagnostic.Error error -> require (error.code = code)
      ("Expected " ^ code ^ ", got " ^ error.code ^ ": " ^ error.message)
let parent maximum = W.create ~profile:"generator_test_parent" ~error_code:"generator_parent_limit" ~maximum ()
let source_mutation_expected = Json.parse {mutation|{"fingerprint":"0a9dadec05cf04ccdf7293e51ddc9963380aa321557ac046a01e2899366dbe1f","key":"active:response.rest","result":{"checked_requirement_ids":["response.rest"],"claim_scope":"Only the listed contract requirements, supplied input history, operating domain, and finite evaluation horizon were checked; this is not whole-program or universal biological refinement.","counterexamples":[],"coverage":[],"dependencies":{"behavior":"6cb1afa58cea00a4b4c78a113afeae0b99fc1200927af8e453fe202d37804895","behavior_artifact":"2dfb119b1cde0a5536e957bf5d466d7783630964562dfb65fb083c26b6e251b0","checker":"biocompiler.realization_checker.v0.3","contract":"2da91d5122320b0a11bd8d260af81f173226beb3cef7c51addf0d6765f12f9cd","domain":"abf5a4895fe59067b2a34123af5777727ebc7e2654b042d9ad480f5134836ea7","history":"4f53cda18c2baa0c0354bb5f9a3ecbe5ed12ab4d8e11ba873c2f11161202b945","horizon":{"effective":7,"until":7},"mechanism":"0a732634f98719282cb3babea0a6df86babf597e65a0547b1635da4370f6f10e","model_runner":"biocompiler.synthetic.runner.v0.2","observation_map":"fa34305bcfe50dac18ae0461dc8823265899319aae37adb2fc075e53efb2265b","reference_evaluator":"biocompiler.behavior.evaluator.v0.2","settings":{"catalog":"f2a4b4c1625b4794028fcd1d0e08785724f957023966a29faafe9374cca77343","contact_loss":"cancel_contact_scoped_obligations","coverage":"all_selected_role_ongoing_outputs","generator_configuration":"9e05501669a1dac6e11eeaa81e5b9fb635689c925bb6f29a6b459c9d26a72995","human_admission_policy":"biocompiler.human_admission_policy.v0.1","intended_use":"software_test","max_microsteps":1000,"nonvacuity":"checked_active_and_inactive_deadlines_for_every_response_and_complete_uncancelled_episodes","realization_request":"2f9a6711780e404cf7e1f0c5a6a23bb2f737f82050c86b368784a1ba70901b2d","required_coverage":"active_and_inactive_deadlines_for_every_response","response":"active_inactive_bands_after_transition_deadlines","scope":"supplied_contracts_and_finite_history","synthetic_acceptance":"biocompiler.synthetic.acceptance.v0.5","synthetic_candidate":"ef12a952f5ee2501eaf42f4cd66bdb8d1c51344d974ef0b4ca88cbf65e6d0b61","synthetic_profile":"biocompiler.synthetic.combinational.v0.1","time":"right_continuous_piecewise_constant"},"target":"e796a2182acd84f8b40a525412a81a927f0eac01ed459dab16ae65cf11af208c"},"diagnostics":[{"code":"candidate_lineage","message":"Source correspondence or requirement lineage differs from the declared generation profile.","node_id":null,"requirement_id":null,"source":null}],"evidence_kind":"model_conditional","outcome":"fail","schema_version":"biocompiler.realization_check.v0.1"}}|mutation}

let () =
  List.iter check_literal literal_texts;
  let first = Json.parse (List.hd literal_texts) in
  let request, config = arguments first in
  let candidate, usage = G.generate_with_usage ?config request in
  let fingerprint = A.Candidate.fingerprint candidate in
  (* Independently retained original Python rejection of corrupted producer
     lineage. The checker receives the mutated actual candidate, not a producer
     witness or expected graph. Full report/dependencies must still agree. *)
  let raw_candidate = A.Candidate.to_json candidate in
  let mapping = field "source_map" raw_candidate in
  let key = Json.string (field "key" source_mutation_expected) in
  let mapping = Json.Object (Measurement_contract.replace key (Json.Array [Json.String "unknown_source"])
      (Json.object_fields mapping)) in
  let mutant = A.Candidate.of_json (Json.Object (Measurement_contract.replace "source_map" mapping
      (Json.object_fields raw_candidate))) in
  let report = Bioc_realization_checker.Synthetic_candidate_check.check ~until:(Runtime_number.of_int 7)
      request mutant [] in
  require (same_json (Realization_evidence.Check_result.to_json report) (field "result" source_mutation_expected) &&
      Realization_evidence.Check_result.fingerprint report = Json.string (field "fingerprint" source_mutation_expected))
    "Independent checker accepted or reinterpreted corrupt producer correspondence";
  let check ?limits ?parent () =
    let actual, measured = G.generate_with_usage ?config ?limits ?parent request in
    require (A.Candidate.fingerprint actual = fingerprint) "Reduced budgets changed proposal meaning";
    measured in
  require (usage.work_charged > 1 && usage.report_bytes > 1 && usage.request_bytes > 1 && usage.retained_peak > 1)
    "Missing generator accounting";
  ignore (check ~limits:(G.make_limits ~max_work:usage.work_charged ()) ());
  rejected "realization_work_limit" (fun () -> check ~limits:(G.make_limits ~max_work:(usage.work_charged - 1) ()) ());
  ignore (check ~limits:(G.make_limits ~max_request_bytes:usage.request_bytes ()) ());
  rejected "realization_input_limit" (fun () -> check ~limits:(G.make_limits ~max_request_bytes:(usage.request_bytes - 1) ()) ());
  ignore (check ~limits:(G.make_limits ~max_report_bytes:usage.report_bytes ()) ());
  rejected "realization_report_limit" (fun () -> check ~limits:(G.make_limits ~max_report_bytes:(usage.report_bytes - 1) ()) ());
  ignore (check ~limits:(G.make_limits ~max_monitor_items:usage.retained_peak ()) ());
  rejected "realization_monitor_limit" (fun () -> check ~limits:(G.make_limits ~max_monitor_items:(usage.retained_peak - 1) ()) ());
  rejected "realization_report_limit" (fun () -> check ~limits:(G.make_limits ~max_report_nodes:1 ()) ());
  rejected "realization_limits" (fun () -> G.make_limits ~max_work:50_000_001 ());
  rejected "realization_limits" (fun () -> G.make_limits ~max_monitor_items:0 ());
  let exact_parent = parent usage.work_charged in
  let measured = check ~parent:exact_parent () in
  require (W.remaining exact_parent = 0 && measured.work_charged = usage.work_charged)
    "Source checking and generation did not consume one ancestor work allowance";
  let short_parent = parent (usage.work_charged - 1) in
  (match check ~parent:short_parent () with
   | _ -> failwith "One-under parent accepted"
   | exception Diagnostic.Error error ->
       require (error.code = "generator_parent_limit" && W.is_exhaustion short_parent error)
         "Parent exhaustion was rewritten as unsupported generation");
  (* Repeating an unsupported operation consumes ancestor work on every call.
     Neither a semantic failure nor a resource failure poisons fresh sessions. *)
  let bad = List.find (fun text -> Json.string (field "outcome" (Json.parse text)) = "raised") literal_texts |> Json.parse in
  let bad_request, bad_config = arguments bad in
  let shared = parent 50_000_000 in
  let failed () =
    let before = W.remaining shared in
    (match G.generate ?config:bad_config ~parent:shared bad_request with
     | _ -> failwith "Previously unsupported request became accepted"
     | exception G.Unsupported _ -> ());
    require (W.remaining shared < before) "Failed proposal bypassed ancestor accounting" in
  failed (); failed (); ignore (check ());
  List.iter (fun label ->
      let raw = List.find (fun text -> Json.string (field "id" (Json.parse text)) = label)
          literal_texts |> Json.parse in
      let request, config = arguments raw in
      let expected, used = G.generate_with_usage ?config request in
      let exact = G.generate ?config ~limits:(G.make_limits ~max_monitor_items:used.retained_peak ()) request in
      require (A.Candidate.fingerprint exact = A.Candidate.fingerprint expected)
        (label ^ ": exact retained-state allowance changed meaning");
      rejected "realization_monitor_limit" (fun () -> G.generate ?config
          ~limits:(G.make_limits ~max_monitor_items:(used.retained_peak - 1) ()) request))
    ["independent_source:signature_depth"; "independent_source:shared_observation_fanout";
     "independent_source:memory_signature_alias"];
  (* A structural request import cannot bypass the independently checked source
     and exact contract identity required by public production. *)
  let raw = Realization_request.to_json request in
  let contract = field "contract" raw in
  let contract = Json.Object (Measurement_contract.replace "behavior_fingerprint" (Json.String (String.make 64 '0'))
      (Json.object_fields contract)) in
  let changed = Realization_request.of_json (Json.Object (Measurement_contract.replace "contract" contract (Json.object_fields raw))) in
  rejected "realization_request_behavior_identity" (fun () -> G.generate ?config changed);
  (* Propose retains hard-rejected graphs; public generate applies both hard
     violations in their original operator-then-count order. *)
  let raw = Realization_request.to_json request in
  let build = field "build_request" raw in
  let constraints = Json.Object ["allowed_operators",Json.Array [];"max_gate_count",Json.int 0] in
  let build = Json.Object (Measurement_contract.replace "implementation_constraints" constraints (Json.object_fields build)) in
  let constrained = Realization_request.of_json (Json.Object (Measurement_contract.replace "build_request" build (Json.object_fields raw))) in
  let proposal = G.propose ?config constrained in
  require (Mechanism.fingerprint (A.Candidate.mechanism proposal) = Mechanism.fingerprint (A.Candidate.mechanism candidate))
    "Hard policy altered proposal graph";
  (match G.generate ?config constrained with
   | _ -> failwith "Hard-rejected proposal was generated"
   | exception G.Unsupported error ->
       require (error.node_id = None && error.source = None) "Hard rejection invented source coordinates";
       require (error.message = "Synthetic proposal violates hard constraints: operator_not_allowed:and,any_contact,constant,input,output,select; gate_count_exceeded:3>0")
         "Hard policy rejection order changed");
  print_endline "synthetic generator: 22 complete independent candidates, 19 exact source-bearing rejections, policy and shared exact resource boundaries passed"
